The invariant is `0 <= size <= 17`: `head` identifies the oldest element, and logical element `i` occupies `(head + i) % 17`. Push rejects a full queue without changing it; pop rejects an empty queue without changing it. Modulo indexing preserves FIFO order when the storage wraps around.

```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>
#include <stdexcept>

class BoundedFIFO {
public:
    static constexpr std::size_t capacity = 17;

    bool push(int value) {
        if (size_ == capacity) return false;
        data_[(head_ + size_) % capacity] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % capacity;
        --size_;
        return value;
    }

    std::size_t size() const noexcept { return size_; }

private:
    std::array<int, capacity> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

void require(bool condition, const char* message) {
    if (!condition) throw std::runtime_error(message);
}

int main() {
    try {
        BoundedFIFO queue;
        require(!queue.pop().has_value(), "Initial empty pop failed");

        // Fill, reject overflow, and drain in FIFO order.
        for (int i = 0; i < 17; ++i)
            require(queue.push(i), "Fill failed");
        require(!queue.push(99), "Overflow was accepted");
        require(queue.size() == 17, "Overflow changed size");
        for (int i = 0; i < 17; ++i)
            require(queue.pop() == std::optional<int>{i},
                    "First drain order failed");
        require(queue.size() == 0, "Drain did not empty queue");
        require(!queue.pop().has_value(), "Empty pop failed");

        // Retain four elements, then append across the array boundary.
        for (int i = 0; i < 12; ++i)
            require(queue.push(i), "Wrap setup push failed");
        for (int i = 0; i < 8; ++i)
            require(queue.pop() == std::optional<int>{i},
                    "Wrap setup pop failed");
        for (int i = 12; i < 25; ++i)
            require(queue.push(i), "Wrapped push failed");
        require(queue.size() == 17, "Wrapped size incorrect");
        require(!queue.push(25), "Wrapped overflow accepted");
        for (int i = 8; i < 25; ++i)
            require(queue.pop() == std::optional<int>{i},
                    "Wrapped FIFO order failed");
        require(queue.size() == 0, "Wrapped drain failed");
        require(!queue.pop().has_value(), "Final empty pop failed");

        std::cout << "All tests passed\n";
        return 0;
    } catch (const std::exception& error) {
        std::cerr << error.what() << '\n';
        return 1;
    }
}
```

